def restock(stock: dict[str, int], orders: list[tuple[str, int]]) -> dict[str, int]:
    ledger = dict(stock)  # copy: the input is the opening count, not ours to change
    for item, qty in orders:
        if qty > 0:
            ledger[item] = ledger.get(item, 0) + qty
        elif qty < 0 and ledger.get(item, 0) >= -qty:
            # A sale that can't be covered in full is rejected, and an unknown
            # item isn't created by a rejected sale.
            ledger[item] += qty
    return ledger

code.rust:
use std::collections::{BTreeMap, HashMap};

fn restock(stock: HashMap<String, i64>, orders: Vec<(String, i64)>) -> BTreeMap<String, i64> {
    // A BTreeMap keeps the ledger sorted by name; it serializes to the same
    // JSON object a HashMap would, since object keys have no order.
    let mut ledger: BTreeMap<String, i64> = stock.into_iter().collect();
    for (item, qty) in orders {
        if qty > 0 {
            *ledger.entry(item).or_insert(0) += qty;
        } else if qty < 0 {
            // A sale that can't be covered in full is rejected, and an unknown
            // item isn't created by a rejected sale.
            if let Some(have) = ledger.get_mut(&item) {
                if *have >= -qty {
                    *have += qty;
                }
            }
        }
    }
    ledger
}
